using Microsoft.Xna.Framework;
using System.Text.Json;
namespace StarlightSyndicateDemo;
public static class StageBTests
{
 public static void Run()
 {
  SkillCatalog.VerificationAllV=false;int checks=0;
  void Check(bool ok,string label){if(!ok)throw new Exception("STAGE B FAIL: "+label);checks++;Console.WriteLine("STAGE B PASS: "+label);}
  bool Near(double a,double b,double tolerance=.00001)=>Math.Abs(a-b)<=tolerance;
  var previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"starlight-b-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
  try{
   Check(Near(TacticalRulesB.StackWeight(0),1),"first stack full strength");Check(Near(TacticalRulesB.StackWeight(1),.86911998),"independent second modifier fixture");Check(Near(TacticalRulesB.StackWeight(2),.57058314),"independent third modifier fixture");Check(Near(DemoWorld.StackMultiplier([.5f,.5f]),.282720005),"two webs use corrected penalty");Check(Near(DemoWorld.StackMultiplier([1.5f],true),2.5),"positive bonus above 100 percent is not clamped");
   Check(Near(TacticalRulesB.TurretProbability(1000,1000,1,40,500,0,40),1),"zero angular within optimal");Check(Near(TacticalRulesB.TurretProbability(1000,1000,1,40,2000,0,40),.5),"one falloff yields half chance");Check(Near(TacticalRulesB.TurretProbability(1000,1000,1,40,3000,0,40),.0625),"two falloff fixture");Check(TacticalRulesB.TurretProbability(1000,0,1,40,1001,0,40)==0,"no falloff has a hard limit");Check(TacticalRulesB.TurretProbability(1000,1000,1,40,500,10,1)<.001,"high angular small signature misses");Check(Near(TacticalRulesB.HitQuality(.5f,.4),.89),"quality is correlated to successful attack roll");Check(Near(TacticalRulesB.HitQuality(.5f,.005),3),"wrecking hit fixture");Check(TacticalRulesB.HitQuality(.005f,.007)==0,"wrecking does not bypass failed hit roll");
   Check(Near(DemoWorld.MissileApplication(40,0,80,100,.5f),.5),"stationary small missile target still signature limited");Check(Near(DemoWorld.MissileApplication(80,400,80,100,.5f),.5),"velocity application fixture");Check(DemoWorld.MissileApplication(0,0,80,100,.5f)==0,"zero signature has zero application");
   float whole=TacticalRulesB.RechargeAfter(25,100,100,10),parts=25;for(int i=0;i<100;i++)parts=TacticalRulesB.RechargeAfter(parts,100,100,.1f);Check(Near(whole,parts,.0002),"recharge is frame partition independent");Check(Near(whole,48.543920058,.001),"closed recharge numeric fixture");Check(TacticalRulesB.RechargeAfter(0,100,100,10)==0,"exactly empty recharge boundary");
   var ship=new Ship();var trace=ship.ExplainAttribute("cpuOutput");Check(trace.Context.Owner==ship.InstanceId&&trace.Steps.Length==12,"attribute graph has explicit owner and stage order");Check(Near(trace.Value,ship.Stat("cpuOutput")),"trace equals live stat");double cpu=ship.Stat("cpuOutput");ship.SkillLevels[SkillCatalog.Id("CPU Management")]=1;ship.ClearSkillCache();Check(Near(ship.Stat("cpuOutput"),cpu*1.05),"CPU skill I uses source modifier once");ship.SkillLevels[SkillCatalog.Id("CPU Management")]=5;ship.ClearSkillCache();Check(Near(ship.Stat("cpuOutput"),cpu*1.25),"CPU skill V uses source modifier once");ship.SkillLevels.Clear();ship.ClearSkillCache();Check(Near(ship.Stat("cpuOutput"),cpu),"removing skill restores original stat");
   var clone=FittingSimulation.Copy(ship);foreach(var (key,value) in ship.TacticalSnapshot())Check(Near(value,clone.Stat(key)),"simulator and live / "+key);
   var gun=WeaponState.Create("rail");var q=TacticalRulesB.Weapon(ship,gun);Check(Near(q.Packet.Total,23),"shared catalogue volley");gun.Overheat=true;var hot=TacticalRulesB.Weapon(ship,gun);Check(Near(hot.Packet.Total/q.Packet.Total,1.15)&&Near(hot.Cycle/q.Cycle,.85),"weapon overload changes shared projection");gun.Burnt=true;ship.Weapons=[gun];Check(ship.WeaponDps==0,"burnt gun excluded from fitting DPS");gun.Burnt=false;gun.Online=false;Check(ship.WeaponDps==0,"offline gun excluded from fitting DPS");
   ship=new Ship();ship.SetStat("shieldEmDamageResonance",1);ship.SetStat("shieldThermalDamageResonance",0);ship.SetStat("armorEmDamageResonance",1);ship.SetStat("armorThermalDamageResonance",1);var hit=TacticalRulesB.Damage(ship,new(100,100,0,0),50,100,100);Check(Near(hit.Shield,0)&&Near(hit.Armor,0)&&Near(hit.Hull,100),"mixed packet spills proportional raw damage across layers");
   ship.SetStat("shieldEmDamageResonance",0);var emptyShield=TacticalRulesB.Damage(ship,new(10,0,0,0),0,100,100);Check(Near(emptyShield.Armor,90),"empty perfectly resistant layer cannot absorb incoming damage");
   ship.SupportEffects=[new(){Key="a",Burst=true,Left=10,Bonuses=new(){["maxVelocity"]=.1f}},new(){Key="b",Burst=true,Left=5,Bonuses=new(){["maxVelocity"]=.2f}}];Check(Near(ship.SupportFactor("maxVelocity"),1.2),"unequal same-attribute boosters select strongest across payload keys");ship.SupportEffects[1].Left=0;Check(Near(ship.SupportFactor("maxVelocity"),1.1),"weaker burst resumes after stronger expiry");
   var w=new DemoWorld();w.NewGame(0);w.IgnoreSkillRequirements=true;w.WalletFunds=100000;w.Player.Weapons=[WeaponState.Create("rail"),WeaponState.Create("missile")];w.Player.UtilityFit="";w.Player.Weapons[0].Overheat=true;w.ApplyModuleHeat(w.Player.Weapons[0],.2f);Check(w.Player.RackHeat[0]>0&&w.Player.Weapons[1].Damage>0,"high rack heat reaches adjacent module");string identity=w.Player.Weapons[0].InstanceId;w.Player.Weapons[0].Damage=.99f;w.ApplyModuleHeat(w.Player.Weapons[0],.2f);Check(w.Player.Weapons[0].Burnt,"overloaded gun burns out");Check(w.UnfitLayoutWeapon(0)&&w.WeaponStorage.Single(s=>s.State.InstanceId==identity).State.Burnt,"conditioned gun unfit preserves instance");w.Hangar["rail"]=1;Check(w.FitWeapon("rail",true,0)&&w.Player.Weapons[0].InstanceId==identity&&w.Player.Weapons[0].Burnt,"refit preserves burnout and identity");Check(w.RepairTacticalModule(FittingLayoutModel.Installed(w.Player).First(m=>m.Kind=="weapon"&&m.Index==0))&&!w.Player.Weapons[0].Burnt,"paid station repair restores activation");
   w.Player.Weapons[0].Damage=.2f;w.CargoItems["dc_paste"]=10;Check(w.RepairWithNanites("weapon",0),"weapon nanite repair consumes real supplies");Check(w.StackCount("dc_paste",false)==6,"nanite paste charged exactly once");w.UpdateNaniteRepairs(30);Check(w.Player.Weapons[0].Damage==0&&w.Player.NaniteJobs.Count==0,"nanite job completes against exact instance");
   w.EnterGrid("belt",false);w.Targets.Clear();var npc=new Ship();npc.Weapons=[WeaponState.Create("rail")];npc.Weapons[0].Loaded=3;var enemy=new SpaceTarget{Id="tactical-npc",Kind=TargetKind.Raider,Profile=npc,Position=new(500,0,0),LockId="player",Shield=100,Armor=100,Hull=100,Cap=npc.MaxCap,TacticalProvisioned=true};w.Targets.Add(enemy);float hp=w.Player.Shield+w.Player.Armor+w.Player.Hull;w.UpdateNpcCombatB(.05f);Check(w.Player.Shield+w.Player.Armor+w.Player.Hull<hp&&enemy.Profile.Weapons[0].Loaded==2,"NPC fitted gun uses shared packet and real magazine");Check(w.CombatEvents.Any(e=>e.Source==enemy.Id),"NPC attack has tactical event evidence");
   var ew=EwarCatalog.All.First(e=>e.Kind==EwarKind.ECM);w.EwarEffects.Add(new(){Kind=EwarKind.ECM,SourceId=enemy.Id,TargetId="player",Remaining=10,Strength=1});Check(w.CanLock("player",enemy.Id),"ECM victim can still target jammer");w.Targets.Add(new(){Id="other",Kind=TargetKind.Raider,Profile=new Ship(),Position=new(500,0,0)});Check(!w.CanLock("player","other"),"ECM blocks non-jammer");w.EwarEffects.Clear();Check(w.CanLock("player","other"),"expired EWAR restores lock eligibility");
   w.SupportDockLock=60;Check(!w.CanUseGate("player")&&!w.CanDockAtStructure("player"),"command burst weapons timer blocks gate and dock");w.SupportDockLock=0;
   ulong rng=w.TacticalRandomState;double next=w.CombatRoll();w.TacticalRandomState=rng;w.SimulationPaused=true;DateTime clock=w.Now;w.Update(1);Check(w.Now==clock,"pause freezes tactical clock");w.SimulationPaused=false;
   w.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.Player.Weapons[0].InstanceId==identity,"save reload keeps gun identity");Check(loaded.TacticalRandomState==rng&&Near(loaded.CombatRoll(),next),"saved attack RNG resumes exact next roll");Check(loaded.Targets.Single(t=>t.Id==enemy.Id).Profile!.Weapons[0].Loaded==2,"NPC fitted magazine survives reload");Check(Near(loaded.Player.RackHeat[0],w.Player.RackHeat[0]),"rack heat survives reload");
   var repWorld=new DemoWorld();repWorld.NewGame(0);repWorld.IgnoreSkillRequirements=true;repWorld.EnterGrid("belt",false);repWorld.Targets.Clear();var repair=DefenseState.Create(DefenseCatalog.All.First(d=>d.Kind=="ShieldBoost"&&d.Size==1).Id);repWorld.Player.Defense[1]=repair;repair.Overheat=true;repair.Repeat=false;repWorld.Player.Shield=0;repWorld.Player.Cap=repWorld.Player.MaxCap;var rq=repWorld.Player.DefenseQuoteB(repair);float capBefore=repWorld.Player.Cap;Check(repWorld.ToggleDefense(1),"shared repair quote activates live");Check(Near(repWorld.Player.Shield,rq.Amount,.001)&&Near(capBefore-repWorld.Player.Cap,rq.Capacitor,.001)&&Near(repair.CycleLeft,rq.Duration,.001),"predicted repair amount cost and heated duration equal live");Check(Near(repWorld.Player.DefenseCapUse,rq.Capacitor/rq.Duration,.001),"predicted active repair cap rate uses same quote");
   var a=new DemoWorld();a.NewGame(0);a.EnterGrid("belt",false);a.Targets.Clear();a.Player.Order="stop";var b=new DemoWorld();b.NewGame(0);b.EnterGrid("belt",false);b.Targets.Clear();b.Player.Order="stop";DateTime at=a.Now;a.Update(1);for(int i=0;i<10;i++)b.Update(.1f);Check(a.TacticalTick==20&&b.TacticalTick==20,"fixed tactical step independent of incoming frame size");Check(Near((a.Now-at).TotalSeconds,1,.001),"fixed tactical time tracks one second");
   Console.WriteLine($"{checks} Stage B checks passed.");
  }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);Directory.Delete(dir,true);}
 }
}
